{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"JCO just-cause eviction and relocation requirement","requirement":"A landlord may not terminate a residential tenancy in the City of Los Angeles without just cause, and must provide relocation assistance for no-fault evictions such as owner move-in, demolition, or a government order to vacate.","key_value":null,"coverage_conditions":"Most residential rentals in the City of Los Angeles not regulated by the RSO; tenancy covered once the tenant has lived in the unit at least six months or the original lease expired.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rental units in the City of Los Angeles not regulated by the RSO; six-month occupancy or expired lease required"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, some cooperatives, some non-profit homeless facilities and short-term substance-abuse treatment centers, some HACLA or government-owned properties, and RSO-regulated units.","penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Non-payment eviction barred below Fair Market Rent","requirement":"A landlord may not evict a tenant who falls behind in rent unless the amount owed is greater than the Fair Market Rent for the unit's bedroom size.","key_value":"Rent owed above Fair Market Rent (varies by bedroom size)","coverage_conditions":"Applies to all RSO and JCO rental units in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All RSO and JCO rental units in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR). The FMR depends on the bedroom size of the rental unit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act annual rent cap","requirement":"Annual rent increases on covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; the maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% for 8/1/2024–7/31/2025","coverage_conditions":"Rental units more than 15 years old on a rolling basis; single-family homes and condominiums only if not owned by a real estate trust, corporation, or LLC with a corporate member and the required written notice was given.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Rolling 15-year construction cutoff; single-family/condo exemption turns on owner type and written notice"},"exemptions":"Units built within the last 15 years, deed-restricted affordable units, certain dormitories, two-unit properties with an owner-occupied second unit, qualifying single-family homes and condominiums, and units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%. Previously, from August 1, 2023 to July 31, 2024 the maximum annual increase for units subject to AB 1482 was 8.8%.","interaction":"The City's JCO does not regulate rent increases; state AB 1482 governs the amount.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Eviction notices must be filed with LAHD","requirement":"A landlord must file every eviction notice served on a tenant with the Los Angeles Housing Department within three business days of service.","key_value":"3 business days","coverage_conditions":"Applies to all JCO and RSO rental properties in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All JCO and RSO rental properties in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Just Cause For Eviction Ordinance (JCO)","quoted_span":"Applies to all JCO & RSO rental properties – All eviction notices issued to tenants in the City of Los Angeles must be filed with LAHD within three (3) business days of service on the tenant.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
